import{_ as r,a0 as s,w as p,s as a,ao as o,I as n,x as u,a1 as l,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const B=JSON.parse('{"title":"3种方法来创建轻量、持久化的Xubuntu Linux USB系统盘 | LCTT x X-CMD","titleTemplate":false,"description":"3种方法来创建轻量、持久化的Xubuntu Linux USB系统盘 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"3种方法来创建轻量、持久化的Xubuntu Linux USB系统盘 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"3种方法来创建轻量、持久化的Xubuntu Linux USB系统盘 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150119 3 Ways To Create A Lightweight And Persistent Xubuntu Linux USB Drive","title":"3种方法来创建轻量、持久化的Xubuntu Linux USB系统盘","tag":"201502","desc":""},"relativePath":"201502/20150119 3 Ways To Create A Lightweight And Persistent Xubuntu Linux USB Drive.md","filePath":"[post].md"}'),b={name:"201502/20150119 3 Ways To Create A Lightweight And Persistent Xubuntu Linux USB Drive.md"};function d(x,t,U,S,m,T){const i=s("Link");return p(),a("div",null,[t[35]||(t[35]=o('<h1 id="_3种方法来创建轻量、持久化的xubuntu-linux-usb系统盘" tabindex="-1">3种方法来创建轻量、持久化的Xubuntu Linux USB系统盘 <a class="header-anchor" href="#_3种方法来创建轻量、持久化的xubuntu-linux-usb系统盘" aria-label="Permalink to “3种方法来创建轻量、持久化的Xubuntu Linux USB系统盘”">​</a></h1><h3 id="使用universal-usb-install创建持久化usb-xubuntu系统盘" tabindex="-1">使用Universal USB Install创建持久化USB Xubuntu系统盘 <a class="header-anchor" href="#使用universal-usb-install创建持久化usb-xubuntu系统盘" aria-label="Permalink to “使用Universal USB Install创建持久化USB Xubuntu系统盘”">​</a></h3><p><img src="http://f.tqn.com/y/linux/1/S/2/J/1/xubuntudesktop.png" alt=""></p>',3)),n("p",null,[t[1]||(t[1]=u("这个教程为你介绍如何使用Xubuntu Linux创建一个轻量并且",-1)),l(i,{href:"http://www.pendrivelinux.com/what-is-persistent-linux/"},{default:e(()=>[...t[0]||(t[0]=[u("持久化",-1)])]),_:1}),t[2]||(t[2]=u("的Linux USB系统盘。",-1))]),t[36]||(t[36]=o('<blockquote><p>译者注：持久化Linux USB系统盘（Persistent Linux USB drive），安装在优盘的Linux系统，允许用户保存数据到优盘而不是仅仅将这些修改留在内存中。这些数据可以在重启后恢复并且重新使用，甚至是在其他的机器上面启动也没有关系。一般情况下，持久化系统盘会安装一个压缩过的Linux操作系统。</p></blockquote><p>为什么要这样做呢，这里有5个很好的理由：</p><ol><li>你想要在你的电脑上安装一个轻量并且功能完善的Linux版本。</li><li>你的电脑没有硬盘，那么一个Linux USB系统盘就可以让这台电脑摆脱被扔到垃圾堆的命运。</li><li>你想体验一下Linux，但是你却不想花太多的时间去准备。</li><li>你想创建一个USB系统恢复盘，并且在优盘上安装一些特定的应用程序。</li><li>你想要一个可定制的Linux版本，能装在后兜或者挂在钥匙圈上。</li></ol><p>现在，我们有了充足的理由，那么开始做一些准备工作吧。</p><p>如果你使用的是Windows：</p><ol><li>下载Xubuntu。</li><li>下载Universal USB Installer。</li><li>插入一个空的优盘。</li><li>使用Universal USB Installer创建一个常驻系统启动盘。</li></ol><p>如果你使用的是Ubuntu：</p><ol><li>下载Xubuntu。</li><li>使用Ubuntu Startup Creator。</li></ol><p>如果你使用的是其他版本的Linux：</p><ol><li>下载Xubuntu。</li><li>使用UNetbootin。</li></ol><p>还有一些场景，可能需要使用命令行，会更难一些，但是上面列的三种应该已经可以满足大部分的情况。</p><h3 id="下载xubuntu和universal-usb-installer" tabindex="-1">下载Xubuntu和Universal USB Installer <a class="header-anchor" href="#下载xubuntu和universal-usb-installer" aria-label="Permalink to “下载Xubuntu和Universal USB Installer”">​</a></h3><p><img src="http://f.tqn.com/y/linux/1/S/G/J/1/xubuntuwebsite.JPG" alt=""></p>',13)),n("p",null,[t[4]||(t[4]=u("访问",-1)),l(i,{href:"http://xubuntu.org/getxubuntu/"},{default:e(()=>[...t[3]||(t[3]=[u("Xubuntu网站",-1)])]),_:1}),t[5]||(t[5]=u("，然后选一个你喜欢的版本下载。",-1))]),t[37]||(t[37]=n("p",null,"目前有两个版本可供使用：",-1)),n("ul",null,[n("li",null,[l(i,{href:"http://www.dedoimedo.com/computers/xubuntu-trusty.html"},{default:e(()=>[...t[6]||(t[6]=[u("Trusty Tahr (14.04 LTS)",-1)])]),_:1})]),n("li",null,[l(i,{href:"http://www.dedoimedo.com/computers/xubuntu-utopic.html"},{default:e(()=>[...t[7]||(t[7]=[u("Utopic Unicorn (14.10)",-1)])]),_:1})])]),t[38]||(t[38]=n("p",null,"14.04版是一个长期维护的版本，维护周期会持续3年。14.10是最新版本，但是只提供9个月的维护。",-1)),t[39]||(t[39]=n("p",null,"你选择了下载站点以后，会提示你选择32位版本或者64位版本。如果你的电脑是32位，就选32位版本，同样，如果你的电脑是64位，那就选64位版本。",-1)),n("p",null,[l(i,{href:"http://pcsupport.about.com/od/fixtheproblem/f/32-bit-64-bit-windows.htm"},{default:e(()=>[...t[8]||(t[8]=[u("点击这里，有一个教程来教你辨别你的电脑是32位还是64位",-1)])]),_:1}),t[9]||(t[9]=u("。",-1))]),n("p",null,[t[11]||(t[11]=u("可以从",-1)),l(i,{href:"http://www.pendrivelinux.com/universal-usb-installer-easy-as-1-2-3/"},{default:e(()=>[...t[10]||(t[10]=[u("Pendrive Linux网站",-1)])]),_:1}),t[12]||(t[12]=u("下载Universal USB Installer，点击download链接，过一会下载页面就会弹出来了。",-1))]),t[40]||(t[40]=o('<h3 id="使用universal-usb-installer创建一个xubuntu启动优盘" tabindex="-1">使用Universal USB Installer创建一个Xubuntu启动优盘 <a class="header-anchor" href="#使用universal-usb-installer创建一个xubuntu启动优盘" aria-label="Permalink to “使用Universal USB Installer创建一个Xubuntu启动优盘”">​</a></h3><p><img src="http://f.tqn.com/y/linux/1/S/-/J/1/uui1l.JPG" alt=""></p><p>下载完Universal USB Installer和Xubuntu以后，运行Universal USB Installer，出现安全警告时，点击“Accept”。</p><p>Universal USB Installer用来创建一个持久化的Xubuntu启动优盘。</p><p>第一屏是许可协议。点击“I Agree”继续。</p><p><img src="http://f.tqn.com/y/linux/1/S/0/J/1/uui2l.JPG" alt=""></p><p>Universal USB Installer主界面出现以后，从下拉列表中选择你想要的配置（i.e Xubuntu），第二步，点击“Browse”选择你下载的ISO文件的路径。</p><p>在电脑上插入一个空的优盘，然后选中“Showing all drives”复选框。</p><p>在下拉列表中选中你的优盘（一定要确定选的是正确的盘符哦）。如果优盘不是空的，选中格式化复选框。</p><blockquote><p>注：格式化优盘会清除优盘上的所有数据，首先一定要确认是否以及备份过相关的数据。</p></blockquote><p>在第四步中选择用于保存“持久化”系统数据的存储空间大小。</p><p>点击“Create”按钮继续。</p><p><img src="http://f.tqn.com/y/linux/1/S/1/J/1/uu3l.JPG" alt=""></p><p>最后一个界面提示你如果点击“Yes”，那么将会直接应用你的配置。</p><p>这是停止安装的最后一个机会，一定要确定你选了正确的优盘盘符，并且优盘上没有需要备份的其他文件。</p><p>点击“Yes”，然后耐心等待优盘创建完成。</p><blockquote><p>注：创建持久化保存空间会花费一些时间，并且这时候进度条不会继续滚动。</p></blockquote><p>这个过程完成以后，重启电脑，如果从优盘启动，就会加载Xubuntu。</p><h3 id="使用ubuntu的startup-disk-creator创建xubuntu启动优盘" tabindex="-1">使用Ubuntu的Startup Disk Creator创建Xubuntu启动优盘 <a class="header-anchor" href="#使用ubuntu的startup-disk-creator创建xubuntu启动优盘" aria-label="Permalink to “使用Ubuntu的Startup Disk Creator创建Xubuntu启动优盘”">​</a></h3><p><img src="http://f.tqn.com/y/linux/1/S/H/J/1/ubuntustartupdiskcreator.png" alt=""></p><p>如果你已经安装了Ubuntu，那么创建持久化USB Xubuntu系统盘的最简单的办法就是使用Startup Disk Creator。</p><p>按下超级键（Windows键），打开Dash，搜索“Startup Disk Creator”，图标出现以后点击它。</p>',22)),n("p",null,[t[14]||(t[14]=u("如果你对Ubuntu Dash不太熟悉，你可以",-1)),l(i,{href:"http://linux.about.com/od/howtos/fl/Learn-Ubuntu-The-Unity-Dash.htm"},{default:e(()=>[...t[13]||(t[13]=[u("点击这里，查看一个完整的教程",-1)])]),_:1}),t[15]||(t[15]=u("。",-1))]),t[41]||(t[41]=o('<p>Startup Disk Creator使用起来很简单。</p><p>界面被划分成两个部分。上部分指定下载的系统盘路径，下部分指定安装的优盘。</p><p>首先，点击“Other”按钮，第二步，选择你所下载的Xubuntu ISO文件。</p><p>然后插入优盘，点击“Erase”按钮清除优盘数据。</p><blockquote><p>注：点击“Erase”会删除优盘中所有的数据，记得先备份数据。</p></blockquote><p>选中“Stored in reserved extra sapce”单选按钮，然后拖动“How much”来确定你想要用来存储“持久化”数据的空间。</p><p>点击“Make Startup Disk”。</p><p>你创建的过程中，你可能需要输入几次你的系统密码，USB系统盘创建完成以后，你就可以使用它启动到Xubuntu了。</p><h3 id="使用unetbootin创建持久化的xubuntu系统盘" tabindex="-1">使用UNetbootin创建持久化的Xubuntu系统盘 <a class="header-anchor" href="#使用unetbootin创建持久化的xubuntu系统盘" aria-label="Permalink to “使用UNetbootin创建持久化的Xubuntu系统盘”">​</a></h3><p><img src="http://f.tqn.com/y/linux/1/S/I/J/1/unetbootin1.png" alt=""></p><p>我要介绍的最后一个工具是UNetbootin，这个工具在Windows和Linux上都可以使用。</p><p>个人来说，在Windows系统上面我喜欢用Universal USB Installer，但Linux的话，UNetbootin更合适一些。</p><blockquote><p>注：UNetbootin并不是100%完美的，不是所有的Linux发行版都支持。</p></blockquote>',13)),n("p",null,[t[17]||(t[17]=u("Windows平台可以点击",-1)),l(i,{href:"http://linux.about.com/od/howtos/ss/How-To-Create-A-UEFI-Bootable-Ubuntu-USB-Drive-Using-Windows.htm"},{default:e(()=>[...t[16]||(t[16]=[u("这里",-1)])]),_:1}),t[18]||(t[18]=u("下载UNetbootin。",-1))]),t[42]||(t[42]=o("<p>Linux平台可以使用package manager安装UNetbootin。</p><p>确认你的优盘已经连接到电脑上，确认优盘已经格式化，并且在优盘上没有其他的数据。</p><p>在Windows平台上运行UNetbootin只需要双击可执行程序即可，在Linux运行的话则需要提升权限。</p><p>在Linux上如何运行取决于你使用的是何种桌面环境以及Linux发行版。从命令行运行的话，输入下列命令：</p><blockquote><p>sudo unetbootin</p></blockquote><p>UNetbootin的界面分为两个部分。你可以在上半部分选择一个Linux发行版，然后下载它，如果已经下载了某个发行版，可以在下半部分选择已经下载的系统盘。</p><p>点击“Diskimage”单选框，然后点击三个点的按钮。找到已经下载的Xubuntu ISO文件。路径会显示到按钮旁边的文本框里面。</p><p>设置“Space used to preserve files across reboots”的值，来指定你想要用来存储“持久化”数据的空间大小。</p><p>类型选择USB drive，然后选择优盘的盘符。</p><p>点击“OK”来创建一个持久化Xubuntu启动优盘。</p><p>创建的过程要花一些时间，创建完成以后，你就可以通过优盘启动到Xubuntu系统了。</p>",11)),n("p",null,[t[20]||(t[20]=u("如果你想要创建一个支持UEFI的Xubuntu启动优盘，",-1)),l(i,{href:"http://linux.about.com/od/howtos/ss/How-To-Create-A-UEFI-Bootable-Ubuntu-USB-Drive-Using-Windows.htm"},{default:e(()=>[...t[19]||(t[19]=[u("照着这个教程来做",-1)])]),_:1}),t[21]||(t[21]=u("，只需要把Ubuntu ISO替换为Xubuntu ISO就可以了。",-1))]),n("p",null,[t[23]||(t[23]=u("via : ",-1)),l(i,{href:"http://linux.about.com/od/howtos/ss/How-To-Create-A-Persistent-Bootable-Xubuntu-Linux-USB-Drive.htm"},{default:e(()=>[...t[22]||(t[22]=[u("http://linux.about.com/od/howtos/ss/How-To-Create-A-Persistent-Bootable-Xubuntu-Linux-USB-Drive.htm",-1)])]),_:1})]),n("p",null,[t[27]||(t[27]=u("作者：",-1)),l(i,{href:"http://linux.about.com/bio/Gary-Newell-132058.htm"},{default:e(()=>[...t[24]||(t[24]=[u("Gary Newell",-1)])]),_:1}),t[28]||(t[28]=u(" 译者：",-1)),l(i,{href:"https://github.com/Zhouj-sh"},{default:e(()=>[...t[25]||(t[25]=[u("zhouj-sh",-1)])]),_:1}),t[29]||(t[29]=u(" 校对：",-1)),l(i,{href:"https://github.com/carolinewuyan"},{default:e(()=>[...t[26]||(t[26]=[u("Caroline",-1)])]),_:1})]),n("p",null,[t[32]||(t[32]=u("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[30]||(t[30]=[u("LCTT",-1)])]),_:1}),t[33]||(t[33]=u(" 原创翻译，",-1)),l(i,{href:"http://linux.cn/"},{default:e(()=>[...t[31]||(t[31]=[u("Linux中国",-1)])]),_:1}),t[34]||(t[34]=u(" 荣誉推出",-1))])])}const w=r(b,[["render",d]]);export{B as __pageData,w as default};
